// The payment rule: whether an order's lines add up to something billable.

const MINIMUM_PAYABLE_MINOR = 100;

export function orderIsPayable(order) {
	if (!order || !Array.isArray(order.lines)) {
		return false;
	}
	let totalMinor = 0;
	for (const line of order.lines) {
		const quantity = Number(line.quantity ?? 0);
		const unitMinor = Number(line.unitMinor ?? 0);
		if (!Number.isInteger(quantity) || !Number.isInteger(unitMinor)) {
			return false;
		}
		if (quantity <= 0 || unitMinor <= 0) {
			return false;
		}
		totalMinor += quantity * unitMinor;
	}
	return totalMinor >= MINIMUM_PAYABLE_MINOR;
}

// The order total, in minor units.

export function orderTotalMinor(order) {
	let totalMinor = 0;
	for (const line of order?.lines ?? []) {
		totalMinor += Number(line.quantity ?? 0) * Number(line.unitMinor ?? 0);
	}
	return totalMinor;
}

// Shipments. Depends only on the payment rule, not on orders themselves -- that is what breaks the cycle.

import { orderIsPayable } from "./payment.mjs";

export const SHIPMENT_STATES = ["pending", "released", "held"];

export function shipmentStateFor(order) {
	if (!order || !Array.isArray(order.lines) || order.lines.length === 0) {
		return "held";
	}
	if (!orderIsPayable(order)) {
		return "held";
	}
	return order.address ? "released" : "pending";
}

export function describeShipment(order) {
	const state = shipmentStateFor(order);
	const count = (order.lines ?? []).length;
	return `${state}:${count}`;
}

// Order persistence and presentation. Lives outside src/domain/ deliberately: this is the layer allowed to know
// about both the domain rules and the store, so the domain itself does not have to.

import { orderIsPayable } from "../domain/payment.mjs";
import { orderTotalMinor } from "../domain/totals.mjs";
import { describeShipment } from "../domain/shipment.mjs";
import { get, put } from "../infra/db.mjs";

export function saveOrder(order) {
	if (!order?.id) {
		throw new TypeError("an order needs an id before it can be saved");
	}
	const record = {
		id: order.id,
		lines: order.lines ?? [],
		address: order.address ?? null,
		totalMinor: orderTotalMinor(order),
		payable: orderIsPayable(order),
		shipment: describeShipment(order),
	};
	put("orders", order.id, record);
	return record;
}

export function loadOrder(id) {
	const record = get("orders", id);
	if (!record) {
		throw new RangeError(`no order ${id}`);
	}
	return record;
}

export function summariseOrder(id) {
	const record = loadOrder(id);
	const parts = [];
	parts.push(`order ${record.id}`);
	parts.push(`${record.lines.length} line(s)`);
	parts.push(`${record.totalMinor} minor`);
	parts.push(record.payable ? "payable" : "not payable");
	parts.push(`shipment ${record.shipment}`);
	return parts.join(", ");
}

export { orderIsPayable } from "./domain/payment.mjs";
export { orderTotalMinor } from "./domain/totals.mjs";
export { saveOrder, loadOrder, summariseOrder } from "./app/orderService.mjs";
export { shipmentStateFor, describeShipment } from "./domain/shipment.mjs";
export { reset } from "./infra/db.mjs";
